int main(void)
{
    int n;
    if (scanf("%d", &n) != 1)
        return 0;
    if (n <= 0) {
        printf("NO DATA\n");          /* never call malloc(0): result is implementation-defined */
        return 0;
    }

    int *buf = malloc((size_t)n * sizeof *buf);
    if (buf == NULL)
        return 1;

    long long sum = 0;
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &buf[i]) != 1) {
            free(buf);                /* error path frees too */
            return 0;
        }
        sum += buf[i];
    }

    /* x > sum / n  <=>  x * n > sum   (n > 0), exact in 64-bit integers */
    int k = 0;
    for (int i = 0; i < n; i++)
        if ((long long)buf[i] * n > sum)
            k++;

    printf("count=%d\n", k);
    if (k > 0) {
        int printed = 0;
        for (int i = 0; i < n; i++) {
            if ((long long)buf[i] * n > sum) {
                printf("%s%d", printed ? " " : "", buf[i]);
                printed++;
            }
        }
        printf("\n");
    }

    free(buf);
    return 0;
}

