/* Return a new heap copy of s (caller frees), or NULL if s is NULL or malloc fails. */
char *my_strdup(const char *s)
{
    if (s == NULL)
        return NULL;

    size_t len = strlen(s);
    char *p = malloc(len + 1);       /* + 1 for the terminating '\0' */
    if (p == NULL)
        return NULL;

    memcpy(p, s, len + 1);           /* copies the '\0' as well */
    return p;
}

