#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

int uart_getc(void); /* provided by the harness: next byte or -1 at end of stream */

char *read_line(size_t *len)
{
    size_t cap = 16, n = 0;
    char *buf = malloc(cap);
    if (buf == NULL)
        return NULL;

    int c = uart_getc();
    if (c == -1) {                       /* nothing left: end of stream */
        free(buf);
        if (len != NULL)
            *len = 0;
        return NULL;
    }

    while (c != -1 && c != '\n') {
        if (n + 1 >= cap) {              /* keep room for the '\0' */
            if (cap > SIZE_MAX / 2) {
                free(buf);
                return NULL;
            }
            char *tmp = realloc(buf, cap * 2);
            if (tmp == NULL) {           /* do not lose (leak) the old block */
                free(buf);
                return NULL;
            }
            buf = tmp;
            cap *= 2;
        }
        buf[n++] = (char)c;
        c = uart_getc();
    }
    buf[n] = '\0';
    if (len != NULL)
        *len = n;
    return buf;
}

