{
    for (int i = 0; i < q->count; i++) {
        struct msg *m = &q->items[i];
        printf("TX 0x%X [%zu]", m->id, m->len);
        for (size_t k = 0; k < m->len; k++)
            printf(" %02X", m->payload[k]);
        printf("\n");
        msg_destroy(m);
    }
    q->count = 0;
}

